// CAMBIAR la clave antes de usar. Es la misma que se escribe en el panel.
const CLAVE_ADMIN = 'CAMBIAR_CLAVE_ADMIN';
const j = $input.first().json;
const key = (j.headers && (j.headers['x-admin-key'] || '')) || '';
const b = j.body || {};
if (CLAVE_ADMIN === 'CAMBIAR_CLAVE_ADMIN' || key !== CLAVE_ADMIN) {
  return [{ json: { auth: false } }];
}
const f = v => (/^\d{4}-\d{2}-\d{2}$/.test(v || '') ? v : '');
const ESTADOS = ['pendiente', 'confirmada', 'realizada', 'cancelada'];
let query = '', params = [];
if (b.action === 'login') {
  query = 'SELECT 1 AS ok'; params = [];
} else if (b.action === 'listar') {
  query = "SELECT id, codigo, nombre, telefono, email, tipo_propiedad, plaga, comuna, direccion, frecuencia, mensaje, to_char(fecha,'YYYY-MM-DD') AS fecha, bloque_id, estado, notas_internas, created_at FROM reservas WHERE org_id = 'capest' AND fecha BETWEEN $1::date AND $2::date AND ($3 = '' OR estado = $3) ORDER BY fecha, bloque_id, created_at";
  params = [f(b.desde) || '2000-01-01', f(b.hasta) || '2100-01-01', ESTADOS.includes(b.estado) ? b.estado : ''];
} else if (b.action === 'estado' && ESTADOS.includes(b.estado) && /^[0-9a-f-]{36}$/i.test(b.id || '')) {
  query = "UPDATE reservas SET estado = $2, notas_internas = COALESCE(NULLIF($3, ''), notas_internas), updated_at = now() WHERE org_id = 'capest' AND id = $1::uuid RETURNING id, estado";
  params = [b.id, b.estado, String(b.notas || '').slice(0, 600)];
} else if (b.action === 'bloquear' && f(b.fecha)) {
  query = "INSERT INTO bloqueos (org_id, fecha, bloque_id, motivo) VALUES ('capest', $1::date, NULLIF($2, ''), $3) RETURNING id";
  params = [b.fecha, String(b.bloque || '').slice(0, 30), String(b.motivo || '').slice(0, 200)];
} else {
  return [{ json: { auth: true, invalid: true } }];
}
return [{ json: { auth: true, invalid: false, query, params } }];
